const EMBEDDED_SOURCES = {"unreal/__init__.py": "", "unreal/properties.py": "\"\"\"\nproperties.py\n\nSkip m\u00ednimo de propiedades tagged de UObject (UE3).\n\nEn UE3, UObject::Serialize escribe un stream de FPropertyTag hasta\nencontrar el nombre \"None\". Cada tag tiene:\n\n  FName Name\n  FName Type\n  int32 Size\n  int32 ArrayIndex\n  [extra seg\u00fan Type: StructName, EnumName, InnerType, ...]\n  luego Size bytes de valor\n\nPara StaticMesh necesitamos saltar esas propiedades y llegar a la\nparte de serializaci\u00f3n nativa (Bounds, Lods, etc.).\n\nEste m\u00f3dulo solo SALTA; no interpreta valores. Suficiente para\nacercar el cursor al VertexStream.\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom typing import List, Tuple, Optional\n\n\ndef read_fname(data: bytes, off: int, names: List[str]) -> Tuple[str, int]:\n    \"\"\"\n    FName en paquetes UE3: int32 NameIndex + int32 Number.\n    \"\"\"\n    if off + 8 > len(data):\n        raise ValueError(f\"EOF FName @{off}\")\n    idx, number = struct.unpack_from(\"<ii\", data, off)\n    off += 8\n    if idx < 0 or idx >= len(names):\n        return f\"INVALID_NAME_{idx}\", off\n    name = names[idx]\n    if number > 0:\n        name = f\"{name}_{number - 1}\"\n    return name, off\n\n\ndef skip_tagged_properties(data: bytes, off: int, names: List[str], max_props: int = 512) -> int:\n    \"\"\"\n    Avanza off hasta despu\u00e9s del terminador None de las propiedades tagged.\n    Devuelve el nuevo offset.\n    \"\"\"\n    for _ in range(max_props):\n        if off + 8 > len(data):\n            raise ValueError(\n                f\"EOF while reading property tags @{off}. \"\n                \"Failed while skipping UObject tagged properties.\"\n            )\n        name, off2 = read_fname(data, off, names)\n        if name == \"None\":\n            return off2\n\n        # Type\n        type_name, off2 = read_fname(data, off2, names)\n        if off2 + 8 > len(data):\n            raise ValueError(f\"EOF property size @{off2}\")\n        size, array_index = struct.unpack_from(\"<ii\", data, off2)\n        off2 += 8\n\n        if size < 0 or size > len(data):\n            raise ValueError(\n                f\"Property '{name}' type={type_name} size={size} inv\u00e1lido @{off}. \"\n                \"Failed while skipping UObject tagged properties.\"\n            )\n\n        # Campos extra seg\u00fan tipo (UE3)\n        # StructProperty \u2192 StructName (FName)\n        # ByteProperty   \u2192 EnumName (FName)  [a veces]\n        # ArrayProperty  \u2192 InnerType (FName) [variantes]\n        # BoolProperty   \u2192 1 byte value inline en algunos ver; en otros Size incluye el valor\n        extra = 0\n        if type_name == \"StructProperty\":\n            _, off2 = read_fname(data, off2, names)\n        elif type_name == \"ByteProperty\":\n            # en muchas versiones UE3 hay EnumName\n            if off2 + 8 <= len(data):\n                # peek: si parece un name index v\u00e1lido, consumirlo\n                peek_idx = struct.unpack_from(\"<i\", data, off2)[0]\n                if 0 <= peek_idx < len(names):\n                    _, off2 = read_fname(data, off2, names)\n\n        # BoolProperty: en UE3 a menudo el valor es 1 byte y Size=0 o Size=1\n        if type_name == \"BoolProperty\":\n            if size == 0:\n                # valor bool de 1 byte justo despu\u00e9s del tag\n                off2 += 1\n            else:\n                off2 += size\n        else:\n            off2 += size\n\n        if off2 > len(data):\n            raise ValueError(\n                f\"Property '{name}' overruns buffer (end={off2}, len={len(data)}). \"\n                \"Failed while skipping UObject tagged properties.\"\n            )\n        off = off2\n\n    raise ValueError(\n        f\"Too many properties (>{max_props}) without None terminator. \"\n        \"Failed while skipping UObject tagged properties.\"\n    )\n\n\ndef find_after_properties(data: bytes, names: List[str]) -> int:\n    \"\"\"\n    Intenta localizar el final de las tagged properties desde offset 0.\n    Si falla, devuelve 0 (el caller puede seguir con heur\u00edstica global).\n    \"\"\"\n    try:\n        return skip_tagged_properties(data, 0, names)\n    except ValueError:\n        return 0\n", "unreal/bulk.py": "\"\"\"\nbulk.py\n\nHelpers para FByteBulkData / TArray BulkSerialize de UE3.\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom typing import Tuple, Optional\n\n\ndef skip_byte_bulk_data(data: bytes, off: int) -> int:\n    \"\"\"\n    FByteBulkData header (UE3 t\u00edpico):\n      int32 BulkDataFlags\n      int32 ElementCount\n      int32 BulkDataSizeOnDisk\n      int32 BulkDataOffsetInFile   (a veces int64 en versiones nuevas)\n\n    Si los datos est\u00e1n inline, ElementCount bytes siguen.\n    Si est\u00e1n en otro sitio del archivo, solo se salta el header.\n    \"\"\"\n    if off + 16 > len(data):\n        return off\n    flags, count, size_on_disk, offset_in_file = struct.unpack_from(\"<iiii\", data, off)\n    off += 16\n\n    # Flags comunes: 0x1 = StoreInSeparateFile, 0x2 = Optional, etc.\n    STORE_IN_SEPARATE = 0x1\n    NO_DATA = 0x20  # approximate / varies\n\n    if flags & STORE_IN_SEPARATE:\n        return off  # data elsewhere\n    if count <= 0:\n        return off\n    # inline\n    if off + size_on_disk <= len(data) and size_on_disk >= 0:\n        return off + size_on_disk\n    if off + count <= len(data):\n        return off + count\n    return off\n\n\ndef read_tarray_header(data: bytes, off: int) -> Tuple[int, int]:\n    \"\"\"int32 Count \u2192 (count, new_off).\"\"\"\n    if off + 4 > len(data):\n        raise ValueError(f\"EOF TArray @{off}\")\n    count, = struct.unpack_from(\"<i\", data, off)\n    return count, off + 4\n", "unreal/package_reader.py": "\"\"\"\npackage_reader.py\n\nParser REAL del header de paquetes Unreal Engine 3 / UDK (.udk / .upk),\nverificado byte a byte contra TJBrotherAirDribble.udk (93,609,995 bytes).\n\nEste parser NO asume nada: cada offset fue derivado leyendo los bytes reales\ndel archivo y verificado contra los conteos que reporta `file` / UModel:\n    names: 661, imports: 129, exports: 2131\n\nEstado verificado (2024, primera corrida real):\n- Tag 0x9E2A83C1                          -> OK\n- Version 868 / Licensee 0 (UDK est\u00e1ndar) -> OK\n- Name table  (661 entradas)               -> OK, strings legibles\n- Import table (129 entradas, 28 bytes c/u)-> OK, referencias a clases\n  reales (Class, Brush, BrushComponent, DirectionalLightComponent, ...)\n- Export table (2131 entradas, 68 bytes c/u) -> OK, termina EXACTO en\n  DependsOffset (165714), sin drift acumulado sobre 2131 registros.\n- 27 exports de clase StaticMesh reales encontrados.\n\nLo que este m\u00f3dulo NO hace todav\u00eda (siguiente etapa, ver README):\n- Deserializar el StaticMesh en s\u00ed (vertex buffers, index buffers, UVs).\n  Eso requiere entender FStaticMeshRenderData / bulk data de UE3, que es\n  el siguiente paso del proyecto (Etapa 2 del plan).\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom dataclasses import dataclass, field\nfrom typing import List, Tuple, Optional\n\nUE3_TAG = 0x9E2A83C1\n\n\ndef read_fstring(data: bytes, off: int) -> Tuple[str, int]:\n    \"\"\"Lee un FString de Unreal (ASCII o UTF-16 seg\u00fan el signo del contador).\"\"\"\n    n, = struct.unpack_from(\"<i\", data, off)\n    off += 4\n    if n == 0:\n        return \"\", off\n    if n < 0:\n        count = -n\n        raw = data[off:off + count * 2]\n        s = raw.decode(\"utf-16-le\", errors=\"replace\").rstrip(\"\\x00\")\n        off += count * 2\n        return s, off\n    raw = data[off:off + n]\n    s = raw.decode(\"latin-1\", errors=\"replace\").rstrip(\"\\x00\")\n    off += n\n    return s, off\n\n\n@dataclass\nclass ImportEntry:\n    class_package: str\n    class_name: str\n    outer_index: int\n    object_name: str\n\n\n@dataclass\nclass ExportEntry:\n    index: int  # 0-based\n    class_index: int\n    super_index: int\n    outer_index: int\n    object_name: str\n    archetype_index: int\n    object_flags: int\n    serial_size: int\n    serial_offset: int\n    export_flags: int\n    guid: bytes\n\n    def class_name(self, imports: List[ImportEntry], exports: List[\"ExportEntry\"]) -> str:\n        if self.class_index == 0:\n            return \"Class\"  # el propio export ES una UClass\n        if self.class_index < 0:\n            return imports[-self.class_index - 1].object_name\n        return exports[self.class_index - 1].object_name\n\n\n@dataclass\nclass PackageSummary:\n    version: int\n    licensee_version: int\n    header_size: int\n    folder_name: str\n    package_flags: int\n    name_count: int\n    name_offset: int\n    export_count: int\n    export_offset: int\n    import_count: int\n    import_offset: int\n    depends_offset: int\n    guid: bytes\n    generation_count: int\n    generations: List[Tuple[int, int, int]]\n    engine_version: int\n    cooker_version: int\n    compression_flags: int\n    num_compressed_chunks: int\n\n\nclass UnrealPackage:\n    \"\"\"\n    Representa un paquete UE3 (.udk/.upk) parseado a partir de bytes reales.\n    Solo implementa lo necesario para llegar a: header -> names -> imports -> exports.\n    \"\"\"\n\n    def __init__(self, path: str):\n        self.path = path\n        with open(path, \"rb\") as f:\n            self.data = f.read()\n\n        self.summary: PackageSummary\n        self.names: List[str] = []\n        self.imports: List[ImportEntry] = []\n        self.exports: List[ExportEntry] = []\n\n        self._parse_summary()\n        self._parse_names()\n        self._parse_imports()\n        self._parse_exports()\n\n    # ------------------------------------------------------------------\n    def _parse_summary(self) -> None:\n        data = self.data\n        off = 0\n\n        tag, = struct.unpack_from(\"<I\", data, off); off += 4\n        if tag != UE3_TAG:\n            raise ValueError(\n                f\"No es un paquete Unreal Engine 3 valido. Tag esperado \"\n                f\"{hex(UE3_TAG)}, encontrado {hex(tag)}\"\n            )\n\n        ver_lic, = struct.unpack_from(\"<I\", data, off); off += 4\n        version = ver_lic & 0xFFFF\n        licensee = (ver_lic >> 16) & 0xFFFF\n\n        header_size, = struct.unpack_from(\"<I\", data, off); off += 4\n\n        folder_name, off = read_fstring(data, off)\n\n        package_flags, = struct.unpack_from(\"<I\", data, off); off += 4\n\n        name_count, name_offset, export_count, export_offset, import_count, import_offset = \\\n            struct.unpack_from(\"<iiiiii\", data, off)\n        off += 24\n\n        depends_offset, = struct.unpack_from(\"<i\", data, off); off += 4\n\n        # Version 868 (UDK estandar) incluye estos 4 campos extra entre\n        # DependsOffset y el Guid. Verificado: sin ellos el Guid/generaciones\n        # quedan desalineados; con ellos, generation_count cae en un valor\n        # razonable (1) y coincide con export_count/name_count.\n        import_export_guids_offset, import_guids_count, export_guids_count, thumbnail_table_offset = \\\n            struct.unpack_from(\"<iiii\", data, off)\n        off += 16\n\n        guid = data[off:off + 16]; off += 16\n\n        generation_count, = struct.unpack_from(\"<i\", data, off); off += 4\n        generations = []\n        for _ in range(generation_count):\n            exp_c, name_c, net_c = struct.unpack_from(\"<iii\", data, off)\n            generations.append((exp_c, name_c, net_c))\n            off += 12\n\n        engine_version, cooker_version = struct.unpack_from(\"<ii\", data, off)\n        off += 8\n\n        compression_flags, = struct.unpack_from(\"<I\", data, off); off += 4\n        num_compressed_chunks, = struct.unpack_from(\"<i\", data, off); off += 4\n\n        if num_compressed_chunks != 0:\n            # Este archivo de prueba no usa chunks comprimidos (num=0).\n            # Si un paquete SI los usa, aqui es donde hay que leerlos:\n            # cada chunk = 4 x int32 (uncompressed offset/size, compressed offset/size)\n            raise NotImplementedError(\n                f\"Paquete con {num_compressed_chunks} chunks comprimidos: \"\n                f\"la decompresion todavia no esta implementada (Etapa siguiente).\"\n            )\n\n        self.summary = PackageSummary(\n            version=version,\n            licensee_version=licensee,\n            header_size=header_size,\n            folder_name=folder_name,\n            package_flags=package_flags,\n            name_count=name_count,\n            name_offset=name_offset,\n            export_count=export_count,\n            export_offset=export_offset,\n            import_count=import_count,\n            import_offset=import_offset,\n            depends_offset=depends_offset,\n            guid=guid,\n            generation_count=generation_count,\n            generations=generations,\n            engine_version=engine_version,\n            cooker_version=cooker_version,\n            compression_flags=compression_flags,\n            num_compressed_chunks=num_compressed_chunks,\n        )\n\n    # ------------------------------------------------------------------\n    def _parse_names(self) -> None:\n        data = self.data\n        off = self.summary.name_offset\n        names = []\n        for _ in range(self.summary.name_count):\n            name, off2 = read_fstring(data, off)\n            # 8 bytes de flags (uint64) por entrada, verificado con datos reales\n            off = off2 + 8\n            names.append(name)\n        self.names = names\n\n    # ------------------------------------------------------------------\n    def _parse_imports(self) -> None:\n        data = self.data\n        off = self.summary.import_offset\n        imports = []\n        for _ in range(self.summary.import_count):\n            (class_pkg_idx, class_pkg_num,\n             class_idx, class_num,\n             outer_index,\n             obj_idx, obj_num) = struct.unpack_from(\"<iiiiiii\", data, off)\n            off += 28\n            imports.append(ImportEntry(\n                class_package=self.names[class_pkg_idx],\n                class_name=self.names[class_idx],\n                outer_index=outer_index,\n                object_name=self.names[obj_idx],\n            ))\n        self.imports = imports\n        expected_end = self.summary.export_offset\n        if off != expected_end:\n            raise ValueError(\n                f\"Import table no termina donde se esperaba: off={off}, \"\n                f\"export_offset={expected_end}. El layout de 28 bytes/import \"\n                f\"no aplica a este archivo.\"\n            )\n\n    # ------------------------------------------------------------------\n    def _parse_exports(self) -> None:\n        data = self.data\n        off = self.summary.export_offset\n        # Formato de 68 bytes derivado y verificado con los datos reales:\n        # ClassIndex, SuperIndex, OuterIndex, NameIndex, NameNumber,\n        # ArchetypeIndex (6 x int32) + ObjectFlags (uint64) +\n        # SerialSize, SerialOffset, ExportFlags, NetObjArrayCount,\n        # NetObjCount[0] (5 x int32) + Guid (16 bytes)\n        fmt = \"<iiiiiiQiiiii16s\"\n        entry_size = struct.calcsize(fmt)\n        assert entry_size == 68\n\n        exports = []\n        for i in range(self.summary.export_count):\n            (class_index, super_index, outer_index, name_idx, name_num,\n             archetype_index, object_flags, serial_size, serial_offset,\n             export_flags, net_obj_array_count, net_obj_count0, guid) = \\\n                struct.unpack_from(fmt, data, off)\n            off += entry_size\n            exports.append(ExportEntry(\n                index=i,\n                class_index=class_index,\n                super_index=super_index,\n                outer_index=outer_index,\n                object_name=self.names[name_idx],\n                archetype_index=archetype_index,\n                object_flags=object_flags,\n                serial_size=serial_size,\n                serial_offset=serial_offset,\n                export_flags=export_flags,\n                guid=guid,\n            ))\n        self.exports = exports\n\n        expected_end = self.summary.depends_offset\n        if off != expected_end:\n            raise ValueError(\n                f\"Export table no termina donde se esperaba: off={off}, \"\n                f\"depends_offset={expected_end}. Hay drift acumulado, revisar \"\n                f\"formato de 68 bytes / generation_count.\"\n            )\n\n    # ------------------------------------------------------------------\n    def find_exports_by_class(self, class_name: str) -> List[ExportEntry]:\n        return [\n            e for e in self.exports\n            if e.class_name(self.imports, self.exports) == class_name\n        ]\n\n    def raw_object_data(self, export: ExportEntry) -> bytes:\n        \"\"\"Devuelve los bytes serializados crudos de un export (aun sin interpretar).\"\"\"\n        return self.data[export.serial_offset: export.serial_offset + export.serial_size]\n", "unreal/static_mesh.py": "\"\"\"\nstatic_mesh.py \u2014 UE3/UDK StaticMesh (Rocket League maps)\n\n12/27 meshes OK on device. Remaining often use bulk payloads or\nlayouts where IB sits far after UV data. Tiny false hits rejected.\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom dataclasses import dataclass\nfrom typing import List, Optional, Tuple\n\ntry:\n    from .properties import find_after_properties\nexcept ImportError:\n    from properties import find_after_properties  # type: ignore\n\n\n@dataclass\nclass MeshGeometry:\n    name: str\n    vertices: List[Tuple[float, float, float]]\n    indices: List[int]\n    uvs: Optional[List[Tuple[float, float]]] = None\n    source_offset: int = 0\n    source_size: int = 0\n    notes: str = \"\"\n\n\ndef _f_ok(x, y, z, lim=1e7):\n    if abs(x) > lim or abs(y) > lim or abs(z) > lim:\n        return False\n    if x != x or y != y or z != z:\n        return False\n    return True\n\n\ndef _read_f3(data, off, count, stride=12, floats=None):\n    \"\"\"floats, if given, is a pre-converted `array('f')` view of the whole\n    buffer at 4-byte alignment (residue 0) \u2014 used by find_loose, where every\n    offset it calls with is guaranteed 4-aligned (stride 12 keeps every\n    subsequent vertex 4-aligned too). Turns what used to be up to 24 sample\n    reads plus a full per-vertex read, each a fresh struct.unpack_from call,\n    into array indexing \u2014 the dominant cost when find_loose has to evaluate\n    thousands of candidate positions on a multi-megabyte mesh.\"\"\"\n    need = count * stride\n    if count < 3 or count > 1_500_000 or off + need > len(data):\n        return None\n    use_fast = floats is not None and stride == 12 and off % 4 == 0\n    base = off // 4 if use_fast else 0\n\n    # Broad, cheap pre-check (up to 24 evenly-spaced samples) before ever\n    # committing to a full read. A full read of up to 1.5M verts is\n    # expensive, and on a multi-megabyte buffer, many coincidental byte\n    # patterns pass a weak 3-point check but fail a broader one \u2014 this is\n    # what keeps find_loose from doing dozens of full-cost reads that all\n    # turn out to be false positives.\n    nsamples = min(24, count)\n    step = max(1, count // nsamples)\n    if use_fast:\n        n = len(floats)\n        for i in range(0, count, step):\n            k = base + i * 3\n            if k + 2 >= n:\n                return None\n            x, y, z = floats[k], floats[k + 1], floats[k + 2]\n            if not _f_ok(x, y, z):\n                return None\n    else:\n        for i in range(0, count, step):\n            x, y, z = struct.unpack_from(\"<fff\", data, off + i * stride)\n            if not _f_ok(x, y, z):\n                return None\n\n    if use_fast:\n        flat = floats[base : base + count * 3]\n        for v in flat:\n            if v != v or abs(v) > 1e7:\n                return None\n        verts = list(zip(flat[0::3], flat[1::3], flat[2::3]))\n    elif stride == 12:\n        # Contiguous floats: one bulk C-level conversion instead of a\n        # per-vertex struct.unpack_from call.\n        flat = struct.unpack_from(f\"<{count * 3}f\", data, off)\n        for v in flat:\n            if v != v or abs(v) > 1e7:\n                return None\n        verts = list(zip(flat[0::3], flat[1::3], flat[2::3]))\n    else:\n        verts = []\n        for i in range(count):\n            x, y, z = struct.unpack_from(\"<fff\", data, off + i * stride)\n            if not _f_ok(x, y, z):\n                return None\n            verts.append((x, y, z))\n    if count >= 6:\n        xs = [v[0] for v in verts]\n        ys = [v[1] for v in verts]\n        zs = [v[2] for v in verts]\n        if (max(xs) - min(xs) < 1e-5 and max(ys) - min(ys) < 1e-5 and max(zs) - min(zs) < 1e-5):\n            return None\n    return verts\n\n\ndef _half_to_float(h):\n    # IEEE 754 half \u2192 float\n    s = (h >> 15) & 1\n    e = (h >> 10) & 0x1F\n    f = h & 0x3FF\n    if e == 0:\n        if f == 0:\n            return -0.0 if s else 0.0\n        return ((-1) ** s) * (f / 1024.0) * (2 ** -14)\n    if e == 31:\n        return float(\"nan\")\n    return ((-1) ** s) * (1 + f / 1024.0) * (2 ** (e - 15))\n\n\ndef _read_f3_half(data, off, count):\n    need = count * 6\n    if count < 3 or off + need > len(data):\n        return None\n    verts = []\n    for i in range(count):\n        hx, hy, hz = struct.unpack_from(\"<HHH\", data, off + i * 6)\n        x, y, z = _half_to_float(hx), _half_to_float(hy), _half_to_float(hz)\n        if not _f_ok(x, y, z):\n            return None\n        verts.append((x, y, z))\n    return verts\n\n\ndef parse_vs_classic(data, start):\n    if start + 8 > len(data):\n        return None\n    vsize, nverts = struct.unpack_from(\"<ii\", data, start)\n    if vsize not in (12, 16, 8, 6) or not (3 <= nverts <= 1_500_000):\n        return None\n    off = start + 8\n\n    if vsize in (12, 16):\n        for label, hdr, use_esize in (\n            (\"bulkB\", 8, True),\n            (\"bulkA\", 4, False),\n            (\"bulkC\", 12, True),\n            (\"direct\", 0, False),\n        ):\n            o = off\n            if label == \"bulkB\" and o + 8 <= len(data):\n                esize, count = struct.unpack_from(\"<ii\", data, o)\n                if esize == vsize and count == nverts:\n                    verts = _read_f3(data, o + 8, nverts, vsize)\n                    if verts:\n                        return verts, o + 8 + nverts * vsize, f\"VS size={vsize} n={nverts} bulkB\"\n            elif label == \"bulkA\" and o + 4 <= len(data):\n                count = struct.unpack_from(\"<i\", data, o)[0]\n                if count == nverts:\n                    verts = _read_f3(data, o + 4, nverts, vsize)\n                    if verts:\n                        return verts, o + 4 + nverts * vsize, f\"VS size={vsize} n={nverts} bulkA\"\n            elif label == \"bulkC\" and o + 12 <= len(data):\n                esize, count, sz = struct.unpack_from(\"<iii\", data, o)\n                if esize == vsize and count == nverts and sz == nverts * vsize:\n                    verts = _read_f3(data, o + 12, nverts, vsize)\n                    if verts:\n                        return verts, o + 12 + sz, f\"VS size={vsize} n={nverts} bulkC\"\n            elif label == \"direct\":\n                if o + nverts * vsize <= len(data):\n                    verts = _read_f3(data, o, nverts, vsize)\n                    if verts:\n                        return verts, o + nverts * vsize, f\"VS size={vsize} n={nverts} direct\"\n\n    # half-float positions (size 6 or 8 with pad)\n    if vsize in (6, 8) and off + nverts * 6 <= len(data):\n        verts = _read_f3_half(data, off, nverts)\n        if verts:\n            return verts, off + nverts * vsize, f\"VS half size={vsize} n={nverts}\"\n\n    return None\n\n\ndef parse_bulk_f3(data, start, max_count=400000, floats=None):\n    if start + 8 <= len(data):\n        esize, count = struct.unpack_from(\"<ii\", data, start)\n        if esize == 12 and 8 <= count <= max_count and start + 8 + count * 12 <= len(data):\n            verts = _read_f3(data, start + 8, count, 12, floats)\n            if verts:\n                return verts, start + 8 + count * 12, f\"rawBulkB n={count}\"\n    if start + 4 <= len(data):\n        count = struct.unpack_from(\"<i\", data, start)[0]\n        if 8 <= count <= max_count and start + 4 + count * 12 <= len(data):\n            verts = _read_f3(data, start + 4, count, 12, floats)\n            if verts:\n                return verts, start + 4 + count * 12, f\"rawBulkA n={count}\"\n    return None\n\n\ndef try_index_buffer(data, start, max_index, ints=None, ints_residue=0):\n    \"\"\"ints, if given, is a pre-converted `array('i')` view of `data` at byte\n    offset `ints_residue` (see find_ib) \u2014 lets the very-hot header-count read\n    be an array index instead of a fresh struct.unpack_from call for every\n    4-byte step of a multi-megabyte buffer.\"\"\"\n    if start + 4 > len(data) or max_index < 2:\n        return None\n\n    def read_i32(off):\n        if ints is not None and off >= ints_residue and (off - ints_residue) % 4 == 0:\n            idx = (off - ints_residue) // 4\n            if idx < len(ints):\n                return ints[idx]\n        return struct.unpack_from(\"<i\", data, off)[0]\n\n    def u16(o, count):\n        if count < 3 or count % 3 or count > 3_000_000 or o + count * 2 > len(data):\n            return None\n        sm = struct.unpack_from(f\"<{min(9, count)}H\", data, o)\n        if max(sm) > max_index:\n            return None\n        idx = list(struct.unpack_from(f\"<{count}H\", data, o))\n        if max(idx) <= max_index and min(idx) >= 0:\n            return idx, o + count * 2\n        return None\n\n    def u32(o, count):\n        if count < 3 or count % 3 or count > 3_000_000 or o + count * 4 > len(data):\n            return None\n        sm = struct.unpack_from(f\"<{min(9, count)}I\", data, o)\n        if max(sm) > max_index:\n            return None\n        idx = list(struct.unpack_from(f\"<{count}I\", data, o))\n        if max(idx) <= max_index and min(idx) >= 0:\n            return idx, o + count * 4\n        return None\n\n    for hdr in (0, 4, 8, 12):\n        off = start + hdr\n        if off + 4 > len(data):\n            continue\n        count = read_i32(off)\n        r = u16(off + 4, count)\n        if r:\n            return r[0], r[1], f\"IB u16 n={count} hdr={hdr}\"\n        r = u32(off + 4, count)\n        if r:\n            return r[0], r[1], f\"IB u32 n={count} hdr={hdr}\"\n\n    if start + 8 <= len(data):\n        esize, count = read_i32(start), read_i32(start + 4)\n        if esize == 2:\n            r = u16(start + 8, count)\n            if r:\n                return r[0], r[1], f\"IB bulk u16 n={count}\"\n        if esize == 4:\n            r = u32(start + 8, count)\n            if r:\n                return r[0], r[1], f\"IB bulk u32 n={count}\"\n    return None\n\n\ndef try_skip_uv(data, start, nverts):\n    if start + 12 > len(data):\n        return None\n    ntc, item_size, nv = struct.unpack_from(\"<iii\", data, start)\n    if not (1 <= ntc <= 8 and 12 <= item_size <= 128 and nv == nverts):\n        return None\n    off = start + 12\n    if off + 4 <= len(data) and struct.unpack_from(\"<i\", data, off)[0] in (0, 1):\n        off += 4\n    for hdr in (0, 4, 8):\n        o = off + hdr\n        if o + 4 > len(data):\n            continue\n        count = struct.unpack_from(\"<i\", data, o)[0]\n        if count != nverts:\n            continue\n        for stride in (item_size, ntc * 8 + 24, ntc * 4 + 12):\n            if o + 4 + count * stride <= len(data):\n                return o + 4 + count * stride\n        if o + 8 <= len(data):\n            es, cnt = struct.unpack_from(\"<ii\", data, o)\n            if cnt == nverts and 8 <= es <= 128 and o + 8 + cnt * es <= len(data):\n                return o + 8 + cnt * es\n    return None\n\n\ndef find_ib(data, verts_end, nverts, max_index, max_scan=2_000_000):\n    \"\"\"Scans for the index buffer following the vertex buffer. The header\n    check at each 4-byte step used to be a fresh struct.unpack_from call \u2014\n    across a multi-megabyte remainder that's millions of Python-level calls.\n    We now bulk-convert the whole remainder to an int32 array once (one C\n    call via the array module) and index into it instead.\n\n    max_scan bounds the worst case: a real index buffer normally follows the\n    vertex buffer closely, not megabytes away, so if nothing turns up within\n    a reasonable window we give up rather than scanning the entire remainder\n    of a multi-megabyte export for a match that (empirically) isn't there.\"\"\"\n    from array import array as _array\n\n    search = verts_end\n    for d in range(0, 256, 4):\n        sk = try_skip_uv(data, verts_end + d, nverts)\n        if sk:\n            search = sk\n            break\n    end = min(len(data) - 8, search + max_scan)\n\n    def scan_from(lo):\n        hi = min(len(data) - 8, lo + max_scan)\n        if lo >= hi:\n            return None\n        residue = lo % 4\n        nints = (len(data) - residue) // 4\n        if nints <= 0:\n            return None\n        ints = _array(\"i\")\n        ints.frombytes(data[residue : residue + nints * 4])\n        start = lo\n        while start < hi:\n            r = try_index_buffer(data, start, max_index, ints, residue)\n            if r:\n                return r\n            start += 4\n        return None\n\n    best = scan_from(search)\n    if best is None and search != verts_end:\n        best = scan_from(verts_end)\n    return best\n\n\ndef find_best_vs(data, scan_from=0):\n    \"\"\"Scans for a plausible vertex-buffer header (vsize in a small known\n    set). Bulk-converts the buffer to an int32 array once instead of one\n    struct.unpack_from call per 4-byte step \u2014 same rationale as find_ib.\"\"\"\n    from array import array as _array\n\n    best = None\n    end = len(data) - 16\n    if end <= 0:\n        return None\n    nints = len(data) // 4\n    ints = _array(\"i\")\n    ints.frombytes(data[: nints * 4])\n\n    def scan(lo, hi):\n        nonlocal best\n        start_idx = (lo & ~3) // 4\n        end_idx = min(hi // 4, len(ints))\n        for i in range(start_idx, end_idx):\n            vs = ints[i]\n            if vs not in (12, 16, 8, 6):\n                continue\n            pos = i * 4\n            r = parse_vs_classic(data, pos)\n            if r and (best is None or len(r[0]) > len(best[0])):\n                best = (r[0], r[1], r[2], pos)\n\n    scan(scan_from, end)\n    if best is None and scan_from > 0:\n        scan(0, min(scan_from, end))\n    return best\n\n\ndef find_loose(data):\n    from array import array as _array\n\n    end = len(data) - 16\n    if end <= 0:\n        return None\n    nints = len(data) // 4\n    ints = _array(\"i\")\n    ints.frombytes(data[: nints * 4])\n    end_idx = min(end // 4, len(ints))\n    floats = _array(\"f\")\n    floats.frombytes(data[: nints * 4])\n\n    cands = []\n    for i in range(0, end_idx):\n        v = ints[i]\n        pos = i * 4\n        if v == 12 and pos + 8 < end:\n            c = ints[i + 1] if i + 1 < len(ints) else struct.unpack_from(\"<i\", data, pos + 4)[0]\n            if 8 <= c <= 300000:\n                r = parse_bulk_f3(data, pos, floats=floats)\n                if r:\n                    cands.append((pos, r))\n        elif 8 <= v <= 300000:\n            r = parse_bulk_f3(data, pos, floats=floats)\n            if r:\n                cands.append((pos, r))\n        if len(cands) > 60:\n            cands.sort(key=lambda x: -len(x[1][0]))\n            cands = cands[:30]\n    cands.sort(key=lambda x: -len(x[1][0]))\n    for pos, (verts, vend, note) in cands[:3]:\n        if len(verts) < 8:\n            continue\n        ib = find_ib(data, vend, len(verts), len(verts) - 1)\n        if ib:\n            return verts, vend, f\"loose {note}\", pos, ib[0], ib[1], ib[2]\n    return None\n\n\ndef find_bounds(data, limit=400_000):\n    \"\"\"Locate a usable bounding box for this mesh, so find_triangle_soup has\n    something to anchor its scan to. Three fingerprints are tried, in order:\n\n    1) FBoxSphereBounds (Origin, BoxExtent, SphereRadius) \u2014 the common case.\n       SphereRadius must equal |BoxExtent| (within tolerance); this is a\n       strong signature that rules out coincidental float matches.\n    2) Plain FBox (Min, Max) \u2014 some custom meshes (seen on flat, custom\n       \"Ground\"-style props with near-zero thickness on one axis) don't carry\n       the sphere-bounds struct at all, or it doesn't pass check (1). Any\n       Max > Min box with at least two axes of real size is accepted; among\n       candidates we prefer the largest footprint, since real bounds tend to\n       dwarf coincidental float matches.\n    3) A percentile-based estimate (1st-99th percentile spread of plausible\n       float3 samples in the buffer) \u2014 last resort when neither struct\n       fingerprint is present at all. Fuzzier, but better than nothing.\n\n    IMPORTANT: fingerprints (1) and (2) are NOT cross-validated against (3).\n    An earlier attempt at that (rejecting a fingerprint match that seemed\n    inconsistent with the percentile estimate) caused severe regressions \u2014\n    it rejected genuinely correct matches on other meshes it had no business\n    touching. (3) only ever runs when (1) and (2) both find nothing.\n\n    All three scans check every byte offset (fields aren't guaranteed 4-byte\n    aligned in this format), so we bulk convert each of the 4 byte alignments\n    to a float array once instead of calling struct.unpack_from per byte.\n    \"\"\"\n    from array import array as _array\n\n    n = min(len(data) - 28, limit)\n    for r in range(4):\n        usable = max(n, 0) - r\n        nfloats = usable // 4\n        if nfloats < 7:\n            continue\n        floats = _array(\"f\")\n        floats.frombytes(data[r : r + nfloats * 4])\n        last_i = nfloats - 7\n        for i in range(0, last_i + 1):\n            ex, ey, ez = floats[i + 3], floats[i + 4], floats[i + 5]\n            if ex < 1.0 or ey < 1.0 or ez < 1.0:\n                continue\n            if ex > 1e5 or ey > 1e5 or ez > 1e5:\n                continue\n            ox, oy, oz = floats[i], floats[i + 1], floats[i + 2]\n            if abs(ox) > 1e5 or abs(oy) > 1e5 or abs(oz) > 1e5:\n                continue\n            rad = floats[i + 6]\n            if rad != rad:\n                continue\n            mag = (ex * ex + ey * ey + ez * ez) ** 0.5\n            if mag < 1e-3:\n                continue\n            if abs(rad - mag) / mag < 0.01:\n                return (ox, oy, oz), (ex, ey, ez), rad\n\n    n2 = min(len(data) - 24, limit)\n    best = None\n    best_area = -1.0\n    for r in range(4):\n        usable = max(n2, 0) - r\n        nfloats = usable // 4\n        if nfloats < 6:\n            continue\n        floats = _array(\"f\")\n        floats.frombytes(data[r : r + nfloats * 4])\n        last_i = nfloats - 6\n        for i in range(0, last_i + 1):\n            minx, miny, minz = floats[i], floats[i + 1], floats[i + 2]\n            maxx, maxy, maxz = floats[i + 3], floats[i + 4], floats[i + 5]\n            if not (maxx >= minx and maxy >= miny and maxz >= minz):\n                continue\n            sx, sy, sz = maxx - minx, maxy - miny, maxz - minz\n            dims = sorted((sx, sy, sz))\n            if dims[1] < 500 or dims[2] > 1e6:\n                continue\n            area = dims[1] * dims[2]  # two largest dims\n            if area > best_area:\n                ex, ey, ez = sx / 2, sy / 2, sz / 2\n                origin = ((minx + maxx) / 2, (miny + maxy) / 2, (minz + maxz) / 2)\n                extent = (max(ex, 1.0), max(ey, 1.0), max(ez, 1.0))\n                radius = (ex * ex + ey * ey + ez * ez) ** 0.5\n                best = (origin, extent, radius)\n                best_area = area\n    if best:\n        return best\n\n    # Last resort: neither an FBoxSphereBounds nor a plain FBox fingerprint\n    # was found. Rather than give up, derive an approximate bounding box from\n    # the 1st-99th percentile spread of every plausible, bounded,\n    # non-degenerate float3 in the buffer. Fuzzier than a real Bounds struct,\n    # but on real geometry data the actual vertex coordinates dominate that\n    # distribution \u2014 verified against a real custom mesh where this\n    # recovered a sane, correctly proportioned result matching its sibling\n    # mesh's scale. Only ever reached when both fingerprints above found\n    # nothing at all \u2014 it does not second-guess a fingerprint match.\n    n3 = min(len(data), limit)\n\n    def _ok(v):\n        return -1e5 < v < 1e5 and v == v and (v == 0 or abs(v) > 1e-3)\n\n    samples_x, samples_y, samples_z = [], [], []\n    for r in range(4):\n        usable = n3 - r\n        nfloats = usable // 4\n        if nfloats < 3:\n            continue\n        floats = _array(\"f\")\n        floats.frombytes(data[r : r + nfloats * 4])\n        for i in range(0, nfloats - 2):\n            x, y, z = floats[i], floats[i + 1], floats[i + 2]\n            if _ok(x) and _ok(y) and _ok(z) and (abs(x) > 1 or abs(y) > 1 or abs(z) > 1):\n                samples_x.append(x)\n                samples_y.append(y)\n                samples_z.append(z)\n    if len(samples_x) < 50:\n        return None\n    samples_x.sort()\n    samples_y.sort()\n    samples_z.sort()\n\n    def pct(a, p):\n        return a[max(0, min(len(a) - 1, int(len(a) * p)))]\n\n    lo = (pct(samples_x, 0.01), pct(samples_y, 0.01), pct(samples_z, 0.01))\n    hi = (pct(samples_x, 0.99), pct(samples_y, 0.99), pct(samples_z, 0.99))\n    dims = tuple(hi[i] - lo[i] for i in range(3))\n    if max(dims) < 10:\n        return None\n    origin = tuple((lo[i] + hi[i]) / 2 for i in range(3))\n    extent = tuple(max(dims[i] / 2, 1.0) for i in range(3))\n    radius = sum(e * e for e in extent) ** 0.5\n    return origin, extent, radius\n\n\ndef _sub(a, b):\n    return (a[0] - b[0], a[1] - b[1], a[2] - b[2])\n\n\ndef _cross(a, b):\n    return (a[1] * b[2] - a[2] * b[1], a[2] * b[0] - a[0] * b[2], a[0] * b[1] - a[1] * b[0])\n\n\ndef _norm(a):\n    return (a[0] ** 2 + a[1] ** 2 + a[2] ** 2) ** 0.5\n\n\ndef find_triangle_soup(data, scan_from, bounds, min_gap=40):\n    \"\"\"Legacy FStaticMeshTriangle fallback: some custom/modded meshes in this\n    package store non-indexed per-triangle wedge data (Vertices[3] followed by\n    variable-length UV/tangent/color blocks) instead of the shared\n    vertex+index buffers the LOD render path uses. We can't reliably predict\n    the per-triangle stride (it depends on NumUVs), so instead of assuming a\n    fixed layout we re-scan for the next valid Vertices[3] pattern anywhere in\n    the buffer. Candidates are constrained to the mesh's own FBoxSphereBounds\n    (with a margin) and to non-degenerate triangle shape, which is what keeps\n    this from turning into noise on multi-megabyte exports.\n\n    Perf note: naive byte-by-byte struct.unpack_from was ~1 python call per\n    byte (multi-minute on a 4-5MB mesh, and since this runs synchronously it\n    froze the browser tab entirely). Instead we bulk-convert each of the 4\n    possible byte alignments to a float array in one C call (array module),\n    then do a cheap first-vertex bbox check as a plain array-index compare\n    before ever touching the expensive edge/area validation.\n    \"\"\"\n    from array import array as _array\n\n    origin, extent, radius = bounds\n    margin = 1.15\n    lox, loy, loz = (origin[i] - extent[i] * margin for i in range(3))\n    hix, hiy, hiz = (origin[i] + extent[i] * margin for i in range(3))\n    diag = 2 * radius\n    min_edge = diag * 0.01\n    min_area = min_edge * min_edge * 0.1\n\n    n = len(data)\n    candidates = []  # (byte_offset, [(x,y,z)*3])\n\n    for r in range(4):\n        usable = n - r\n        nfloats = usable // 4\n        # need 9 floats (3 verts) ahead, and enough trailing bytes for min_gap\n        if nfloats < 9:\n            continue\n        floats = _array(\"f\")\n        floats.frombytes(data[r : r + nfloats * 4])\n        last_i = nfloats - 9\n        i = 0\n        while i <= last_i:\n            x0 = floats[i]\n            if lox <= x0 <= hix:\n                y0 = floats[i + 1]\n                z0 = floats[i + 2]\n                if loy <= y0 <= hiy and loz <= z0 <= hiz:\n                    x1, y1, z1 = floats[i + 3], floats[i + 4], floats[i + 5]\n                    x2, y2, z2 = floats[i + 6], floats[i + 7], floats[i + 8]\n                    if (\n                        lox <= x1 <= hix and loy <= y1 <= hiy and loz <= z1 <= hiz\n                        and lox <= x2 <= hix and loy <= y2 <= hiy and loz <= z2 <= hiz\n                    ):\n                        v0, v1, v2 = (x0, y0, z0), (x1, y1, z1), (x2, y2, z2)\n                        e1, e2, e3 = _sub(v1, v0), _sub(v2, v0), _sub(v2, v1)\n                        if (\n                            min(_norm(e1), _norm(e2), _norm(e3)) >= min_edge\n                            and _norm(_cross(e1, e2)) / 2 >= min_area\n                        ):\n                            candidates.append((r + i * 4, [v0, v1, v2]))\n            i += 1\n\n    candidates.sort(key=lambda c: c[0])\n\n    verts = []\n    indices = []\n    next_ok = scan_from\n    for off, tri in candidates:\n        if off < next_ok:\n            continue\n        base = len(verts)\n        verts.extend(tri)\n        indices.extend((base, base + 1, base + 2))\n        next_ok = off + min_gap\n    return verts, indices\n\n\ndef _valid_mesh(verts, indices):\n    # min 8 verts and at least 1 triangle; prefer real props over noise\n    if len(verts) < 8 or len(indices) < 3:\n        return False\n    if len(indices) % 3:\n        return False\n    return True\n\n\ndef _is_suspicious(verts, indices):\n    \"\"\"A real indexed mesh with hundreds/thousands of vertices normally uses\n    most of them. A tiny index buffer (<=8 tris, <=10 unique verts touched)\n    carved out of a LARGE vertex buffer (>=50 verts) is the signature of a\n    coincidentally-valid few-index match sitting in front of the real index\n    buffer (or of the \"vertex buffer\" match itself being bogus) \u2014 seen in\n    practice on meshes like a \"three\" digit (1248 verts, only 6 referenced)\n    and custom map props (3632-14698 verts, only 3 referenced). Genuinely\n    tiny real meshes (e.g. a 12-vert flat collision plane) never trip this,\n    since the >=50-vert gate only applies to large buffers.\"\"\"\n    if len(verts) < 50:\n        return False\n    tri_count = len(indices) // 3\n    if tri_count > 8:\n        return False\n    return len(set(indices)) <= 10\n\n\ndef extract_geometry(\n    raw: bytes,\n    name: str = \"StaticMesh\",\n    names: Optional[List[str]] = None,\n    ar_ver: int = 868,\n    package_data: Optional[bytes] = None,\n    serial_offset: int = 0,\n) -> MeshGeometry:\n    if len(raw) < 32:\n        raise ValueError(\n            f\"StaticMesh '{name}': bloque demasiado peque\u00f1o ({len(raw)}). \"\n            \"Failed while locating vertex buffers.\"\n        )\n\n    scan_from = 0\n    if names:\n        try:\n            pe = find_after_properties(raw, names)\n            if pe > 0:\n                scan_from = pe\n        except ValueError:\n            pass\n\n    weak = None  # (MeshGeometry) \u2014 a suspicious-but-technically-valid match, kept only if nothing better turns up\n\n    best = find_best_vs(raw, scan_from)\n    if best:\n        verts, vend, note, vstart = best\n        ib = find_ib(raw, vend, len(verts), len(verts) - 1)\n        if ib and _valid_mesh(verts, ib[0]):\n            geo = MeshGeometry(\n                name=name, vertices=verts, indices=ib[0],\n                source_offset=vstart, source_size=ib[1] - vstart,\n                notes=f\"{note} | {ib[2]}\",\n            )\n            if not _is_suspicious(verts, ib[0]):\n                return geo\n            weak = geo\n\n    loose = find_loose(raw)\n    if loose:\n        verts, vend, note, vstart, indices, idx_end, idx_note = loose\n        if _valid_mesh(verts, indices):\n            geo = MeshGeometry(\n                name=name, vertices=verts, indices=indices,\n                source_offset=vstart, source_size=idx_end - vstart,\n                notes=f\"{note} | {idx_note}\",\n            )\n            if not _is_suspicious(verts, indices):\n                return geo\n            weak = weak or geo\n\n    # extended window from package (bulk after export)\n    if package_data is not None and serial_offset >= 0:\n        ext_end = min(len(package_data), serial_offset + len(raw) + 3_000_000)\n        extended = package_data[serial_offset:ext_end]\n        if len(extended) > len(raw) + 64:\n            best = find_best_vs(extended, 0)\n            if best:\n                verts, vend, note, vstart = best\n                ib = find_ib(extended, vend, len(verts), len(verts) - 1)\n                if ib and _valid_mesh(verts, ib[0]):\n                    geo = MeshGeometry(\n                        name=name, vertices=verts, indices=ib[0],\n                        source_offset=vstart, source_size=ib[1] - vstart,\n                        notes=f\"{note} | {ib[2]} | extended\",\n                    )\n                    if not _is_suspicious(verts, ib[0]):\n                        return geo\n                    weak = weak or geo\n\n    # Legacy raw-triangle fallback (custom/modded meshes exported through a\n    # different serialization path than the LOD render data the other\n    # branches above expect). Anchored to the mesh's own Bounds so we don't\n    # pick up UV/tangent/color garbage from elsewhere in the export.\n    bounds = find_bounds(raw)\n    if bounds:\n        verts, indices = find_triangle_soup(raw, scan_from, bounds)\n        if _valid_mesh(verts, indices):\n            geo = MeshGeometry(\n                name=name, vertices=verts, indices=indices,\n                source_offset=scan_from, source_size=len(raw) - scan_from,\n                notes=f\"legacy raw-triangle soup n_tris={len(indices)//3}\",\n            )\n            # triangle-soup candidates are inherently more trustworthy (every\n            # triangle is independently validated against the mesh's own\n            # bounds), so accept even a small one over a suspicious VS/IB hit\n            return geo\n\n    # Nothing fully convincing turned up. A suspicious-but-technically-valid\n    # match beats a hole in the map \u2014 return it, clearly flagged, rather than\n    # failing outright.\n    if weak is not None:\n        weak.notes = f\"LOW-CONFIDENCE (tiny index buffer, likely incomplete) | {weak.notes}\"\n        return weak\n\n    raise ValueError(\n        f\"StaticMesh '{name}': no se encontr\u00f3 geometr\u00eda v\u00e1lida \"\n        f\"(VS/bulk+IB, min 8 verts / 3 tris). size={len(raw)}. \"\n        \"Failed while parsing StaticMesh serialization (position/vertex stream).\"\n    )\n\n\ndef scan_candidate_buffers(raw: bytes, max_hits: int = 20) -> List[str]:\n    lines = []\n    end = len(raw) - 16\n    for pos in range(0, end, 4):\n        if struct.unpack_from(\"<i\", raw, pos)[0] in (12, 16, 8, 6):\n            r = parse_vs_classic(raw, pos)\n            if r:\n                lines.append(f\"  VERT @0x{pos:06x} n={len(r[0]):6d} {r[2]}\")\n                if len(lines) >= max_hits:\n                    break\n    if not lines:\n        lines.append(\"  (no VS candidates)\")\n    return lines\n", "unreal/actors.py": "\"\"\"\nactors.py\n\nExtracci\u00f3n m\u00ednima de StaticMeshActor / transforms desde exports UE3.\n\nObjetivo de esta capa:\n  - Localizar exports de clase StaticMeshActor (y similares)\n  - Leer tagged properties: Location, Rotation, DrawScale3D / Scale3D,\n    StaticMesh (ObjectProperty)\n  - Devolver lista de ActorPlacement listos para montar la escena GLB\n\nNo carga meshes todav\u00eda; solo transforms + nombre del mesh referenciado.\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom dataclasses import dataclass\nfrom typing import List, Optional, Tuple, Any\n\nfrom .properties import read_fname\n\n\n@dataclass\nclass ActorPlacement:\n    name: str\n    mesh_name: str\n    location: Tuple[float, float, float]\n    rotation: Tuple[float, float, float]  # pitch, yaw, roll (grados Unreal) o euler\n    scale: Tuple[float, float, float]\n    export_index: int = -1\n    notes: str = \"\"\n\n\ndef _read_vector(data: bytes, off: int) -> Tuple[Tuple[float, float, float], int]:\n    if off + 12 > len(data):\n        raise ValueError(f\"EOF Vector @{off}\")\n    x, y, z = struct.unpack_from(\"<fff\", data, off)\n    return (x, y, z), off + 12\n\n\ndef _read_rotator(data: bytes, off: int) -> Tuple[Tuple[float, float, float], int]:\n    \"\"\"FRotator: Pitch, Yaw, Roll as float (UE3 often stores as float degrees*...).\"\"\"\n    if off + 12 > len(data):\n        raise ValueError(f\"EOF Rotator @{off}\")\n    p, y, r = struct.unpack_from(\"<fff\", data, off)\n    return (p, y, r), off + 12\n\n\ndef _read_object_index(data: bytes, off: int) -> Tuple[int, int]:\n    \"\"\"ObjectProperty value: int32 package index (negative=import, positive=export).\"\"\"\n    if off + 4 > len(data):\n        raise ValueError(f\"EOF ObjectIndex @{off}\")\n    idx, = struct.unpack_from(\"<i\", data, off)\n    return idx, off + 4\n\n\ndef parse_actor_properties(\n    data: bytes,\n    names: List[str],\n    imports: list,\n    exports: list,\n    actor_name: str = \"Actor\",\n    export_index: int = -1,\n) -> ActorPlacement:\n    \"\"\"\n    Parsea tagged properties de un Actor y extrae Location/Rotation/Scale/StaticMesh.\n    \"\"\"\n    location = (0.0, 0.0, 0.0)\n    rotation = (0.0, 0.0, 0.0)\n    scale = (1.0, 1.0, 1.0)\n    mesh_name = \"\"\n    notes = []\n\n    off = 0\n    max_props = 256\n    for _ in range(max_props):\n        if off + 8 > len(data):\n            break\n        name, off2 = read_fname(data, off, names)\n        if name == \"None\":\n            off = off2\n            break\n\n        type_name, off2 = read_fname(data, off2, names)\n        if off2 + 8 > len(data):\n            break\n        size, array_index = struct.unpack_from(\"<ii\", data, off2)\n        off2 += 8\n\n        if size < 0 or off2 + size > len(data) + 64:\n            # corrupt; abort gracefully\n            notes.append(f\"bad_size:{name}\")\n            break\n\n        # StructProperty extra: StructName\n        struct_name = \"\"\n        if type_name == \"StructProperty\":\n            struct_name, off2 = read_fname(data, off2, names)\n\n        value_off = off2\n\n        try:\n            if name in (\"Location\", \"RelativeLocation\") and type_name == \"StructProperty\":\n                if size >= 12:\n                    location, _ = _read_vector(data, value_off)\n            elif name in (\"Rotation\", \"RelativeRotation\") and type_name == \"StructProperty\":\n                if size >= 12:\n                    rotation, _ = _read_rotator(data, value_off)\n            elif name in (\"DrawScale3D\", \"Scale3D\", \"RelativeScale3D\") and type_name == \"StructProperty\":\n                if size >= 12:\n                    scale, _ = _read_vector(data, value_off)\n            elif name == \"DrawScale\" and type_name == \"FloatProperty\" and size >= 4:\n                s, = struct.unpack_from(\"<f\", data, value_off)\n                scale = (s, s, s)\n            elif name == \"StaticMesh\" and type_name == \"ObjectProperty\" and size >= 4:\n                obj_idx, _ = _read_object_index(data, value_off)\n                mesh_name = _resolve_object_name(obj_idx, imports, exports)\n            elif name in (\"StaticMeshComponent\",) and type_name == \"ObjectProperty\":\n                # reference to component; mesh often on the component itself\n                notes.append(\"has_SMC\")\n        except ValueError as e:\n            notes.append(str(e))\n\n        # advance past value\n        if type_name == \"BoolProperty\" and size == 0:\n            off = value_off + 1\n        else:\n            off = value_off + max(size, 0)\n\n    return ActorPlacement(\n        name=actor_name,\n        mesh_name=mesh_name or \"\",\n        location=location,\n        rotation=rotation,\n        scale=scale,\n        export_index=export_index,\n        notes=\";\".join(notes),\n    )\n\n\ndef _resolve_object_name(index: int, imports: list, exports: list) -> str:\n    if index == 0:\n        return \"\"\n    if index < 0:\n        # import: -index - 1\n        i = -index - 1\n        if 0 <= i < len(imports):\n            return imports[i].object_name\n        return f\"Import[{index}]\"\n    # export: index - 1\n    i = index - 1\n    if 0 <= i < len(exports):\n        return exports[i].object_name\n    return f\"Export[{index}]\"\n\n\ndef find_static_mesh_actors(pkg) -> List[ActorPlacement]:\n    \"\"\"\n    Recorre exports buscando StaticMeshActor (y subclases por nombre)\n    y parsea sus propiedades.\n    \"\"\"\n    results = []\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        # RL/UE3: StaticMeshActor, StaticMeshActor_TA, InterpActor, etc.\n        if \"StaticMeshActor\" not in cname and cname not in (\"Actor\", \"InterpActor\", \"Mover\"):\n            if \"Actor\" not in cname:\n                continue\n        if e.serial_size <= 0:\n            continue\n        raw = pkg.raw_object_data(e)\n        try:\n            place = parse_actor_properties(\n                raw, pkg.names, pkg.imports, pkg.exports,\n                actor_name=e.object_name, export_index=e.index,\n            )\n            results.append(place)\n        except Exception as ex:\n            results.append(ActorPlacement(\n                name=e.object_name,\n                mesh_name=\"\",\n                location=(0, 0, 0),\n                rotation=(0, 0, 0),\n                scale=(1, 1, 1),\n                export_index=e.index,\n                notes=f\"parse_fail:{ex}\",\n            ))\n    return results\n\n\ndef find_mesh_components(pkg) -> List[ActorPlacement]:\n    \"\"\"\n    StaticMeshComponent often holds the actual StaticMesh reference.\n    Outer points to the owning Actor. We recover:\n      component \u2192 StaticMesh name\n      component \u2192 Outer actor name\n      actor \u2192 Location/Rotation/Scale\n    \"\"\"\n    # map export index \u2192 placement from actors\n    actors_by_idx = {}\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        if \"StaticMeshActor\" in cname or cname == \"Actor\":\n            raw = pkg.raw_object_data(e)\n            try:\n                place = parse_actor_properties(\n                    raw, pkg.names, pkg.imports, pkg.exports,\n                    actor_name=e.object_name, export_index=e.index,\n                )\n                actors_by_idx[e.index] = place\n            except Exception:\n                pass\n\n    results = []\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        if \"StaticMeshComponent\" not in cname:\n            continue\n        raw = pkg.raw_object_data(e)\n        try:\n            place = parse_actor_properties(\n                raw, pkg.names, pkg.imports, pkg.exports,\n                actor_name=e.object_name, export_index=e.index,\n            )\n        except Exception:\n            continue\n\n        # OuterIndex of component \u2192 parent actor\n        outer = e.outer_index\n        parent_name = e.object_name\n        parent_loc = place.location\n        parent_rot = place.rotation\n        parent_scale = place.scale\n        if outer > 0:\n            oi = outer - 1\n            if oi in actors_by_idx:\n                parent = actors_by_idx[oi]\n                parent_name = parent.name\n                # prefer actor transform if non-zero\n                if parent.location != (0.0, 0.0, 0.0):\n                    parent_loc = parent.location\n                if parent.rotation != (0.0, 0.0, 0.0):\n                    parent_rot = parent.rotation\n                if parent.scale != (1.0, 1.0, 1.0):\n                    parent_scale = parent.scale\n            elif 0 <= oi < len(pkg.exports):\n                parent_name = pkg.exports[oi].object_name\n\n        if not place.mesh_name:\n            continue\n\n        results.append(ActorPlacement(\n            name=parent_name,\n            mesh_name=place.mesh_name,\n            location=parent_loc,\n            rotation=parent_rot,\n            scale=parent_scale,\n            export_index=e.index,\n            notes=f\"from_component:{e.object_name}\",\n        ))\n    return results\n\n\ndef collect_placements(pkg) -> List[ActorPlacement]:\n    \"\"\"Combina actores directos + componentes; prefiere los que tienen mesh_name.\"\"\"\n    direct = find_static_mesh_actors(pkg)\n    from_comp = find_mesh_components(pkg)\n    by_name = {}\n    for p in direct + from_comp:\n        key = (p.name, p.mesh_name)\n        if p.mesh_name:\n            by_name[key] = p\n        elif key not in by_name:\n            by_name[key] = p\n    return list(by_name.values())\n", "unreal/inventory.py": "\"\"\"\ninventory.py\n\nEverything in a .udk/.upk that this tool otherwise ignores: a full manifest\nof every object the package defines (class, name, size), plus targeted\nextraction of a handful of gameplay-relevant actor classes \u2014 lights, spawn\npoints, goals, boost pads \u2014 and basic material info. StaticMesh geometry\nitself is handled by static_mesh.py; this module is the \"everything else\"\nlayer, informational for classes we don't turn into 3D data (materials,\nKismet, physics) and structural (transform + params) for the ones we do\n(lights, marker actors).\n\nNone of this is required for a mesh to extract correctly \u2014 it's purely\nadditive context about what else lives in the file.\n\"\"\"\n\nfrom __future__ import annotations\nimport struct\nfrom typing import List, Dict, Any, Optional\n\nfrom .properties import read_fname\nfrom .actors import parse_actor_properties, _resolve_object_name\n\n\ndef build_class_inventory(pkg) -> Dict[str, int]:\n    \"\"\"Every export class in the package and how many of each \u2014 the\n    fastest way to see what's actually inside beyond StaticMesh.\"\"\"\n    counts: Dict[str, int] = {}\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        counts[cname] = counts.get(cname, 0) + 1\n    return dict(sorted(counts.items(), key=lambda kv: -kv[1]))\n\n\ndef build_export_list(pkg) -> List[Dict[str, Any]]:\n    \"\"\"Every export: class, name, outer (parent, for nesting), serialized\n    size. This is the raw material for anything not otherwise handled \u2014\n    Kismet sequences, physics assets, particle systems, whatever the map\n    happens to contain.\"\"\"\n    out = []\n    for e in pkg.exports:\n        out.append({\n            \"index\": e.index,\n            \"class\": e.class_name(pkg.imports, pkg.exports),\n            \"name\": e.object_name,\n            \"outer\": e.outer_index,\n            \"size\": e.serial_size,\n        })\n    return out\n\n\ndef build_import_list(pkg) -> List[Dict[str, Any]]:\n    \"\"\"External references \u2014 objects this package uses but doesn't define\n    itself (e.g. a shared texture or material living in Engine.upk).\"\"\"\n    out = []\n    for i, imp in enumerate(pkg.imports):\n        out.append({\n            \"index\": -(i + 1),\n            \"class\": imp.class_name,\n            \"name\": imp.object_name,\n            \"package\": imp.class_package,\n        })\n    return out\n\n\ndef read_simple_properties(data: bytes, names: List[str], max_props: int = 512) -> Dict[str, Any]:\n    \"\"\"Generic tagged-property walker: returns every property this package\n    format can trivially represent (numbers, bools, names, vectors, colors)\n    as a plain dict, skipping (but still advancing past) anything more\n    complex (nested structs/arrays we don't have a specific reader for).\n    This is what powers light color/brightness and material parameters \u2014\n    the same walking logic actors.py uses for Location/Rotation/Scale,\n    generalized to grab everything recognizable instead of a fixed set.\"\"\"\n    out: Dict[str, Any] = {}\n    off = 0\n    for _ in range(max_props):\n        if off + 8 > len(data):\n            break\n        try:\n            name, off2 = read_fname(data, off, names)\n        except ValueError:\n            break\n        if name == \"None\":\n            break\n        try:\n            type_name, off2 = read_fname(data, off2, names)\n        except ValueError:\n            break\n        if off2 + 8 > len(data):\n            break\n        size, array_index = struct.unpack_from(\"<ii\", data, off2)\n        off2 += 8\n        if size < 0 or off2 + size > len(data) + 64:\n            break\n\n        struct_name = \"\"\n        if type_name == \"StructProperty\":\n            try:\n                struct_name, off2 = read_fname(data, off2, names)\n            except ValueError:\n                break\n\n        value_off = off2\n        try:\n            if type_name == \"FloatProperty\" and size >= 4:\n                out[name] = struct.unpack_from(\"<f\", data, value_off)[0]\n            elif type_name == \"IntProperty\" and size >= 4:\n                out[name] = struct.unpack_from(\"<i\", data, value_off)[0]\n            elif type_name == \"BoolProperty\":\n                out[name] = bool(data[value_off]) if size in (0, 1) and value_off < len(data) else None\n            elif type_name == \"ByteProperty\" and size >= 1:\n                out[name] = data[value_off]\n            elif type_name == \"NameProperty\":\n                nval, _ = read_fname(data, value_off, names)\n                out[name] = nval\n            elif type_name == \"StructProperty\" and struct_name in (\"Vector\", \"Rotator\") and size >= 12:\n                out[name] = struct.unpack_from(\"<fff\", data, value_off)\n            elif type_name == \"StructProperty\" and struct_name == \"Color\" and size >= 4:\n                b, g, r, a = struct.unpack_from(\"<BBBB\", data, value_off)\n                out[name] = {\"r\": r, \"g\": g, \"b\": b, \"a\": a}\n            elif type_name == \"StructProperty\" and struct_name == \"LinearColor\" and size >= 16:\n                out[name] = struct.unpack_from(\"<ffff\", data, value_off)\n            elif type_name == \"ObjectProperty\" and size >= 4:\n                out[f\"{name}_ref\"] = struct.unpack_from(\"<i\", data, value_off)[0]\n        except (struct.error, IndexError):\n            pass\n\n        if type_name == \"BoolProperty\" and size == 0:\n            off = value_off + 1\n        else:\n            off = value_off + max(size, 0)\n    return out\n\n\n_LIGHT_CLASSES = (\"DirectionalLight\", \"PointLight\", \"SpotLight\")\n_LIGHT_GLTF_TYPE = {\"DirectionalLight\": \"directional\", \"PointLight\": \"point\", \"SpotLight\": \"spot\"}\n\n\ndef extract_lights(pkg) -> List[Dict[str, Any]]:\n    \"\"\"Light actors (position/rotation from the actor, color/intensity from\n    its *LightComponent child, which is a separate export whose Outer points\n    back at this actor \u2014 same parent/child pattern StaticMeshActor uses for\n    its StaticMeshComponent).\"\"\"\n    lights = []\n    actor_by_idx = {}\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        if any(cname.startswith(lc) and \"Component\" not in cname for lc in _LIGHT_CLASSES):\n            raw = pkg.raw_object_data(e)\n            try:\n                place = parse_actor_properties(raw, pkg.names, pkg.imports, pkg.exports,\n                                                actor_name=e.object_name, export_index=e.index)\n                actor_by_idx[e.index] = (e, place)\n            except Exception:\n                continue\n\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        if \"LightComponent\" not in cname:\n            continue\n        outer = e.outer_index\n        if outer <= 0:\n            continue\n        oi = outer - 1\n        if oi not in actor_by_idx:\n            continue\n        actor_e, place = actor_by_idx[oi]\n        actor_cname = actor_e.class_name(pkg.imports, pkg.exports)\n        light_type = next((_LIGHT_GLTF_TYPE[lc] for lc in _LIGHT_CLASSES if actor_cname.startswith(lc)), \"point\")\n\n        raw = pkg.raw_object_data(e)\n        props = read_simple_properties(raw, pkg.names)\n        color = props.get(\"LightColor\", {\"r\": 255, \"g\": 255, \"b\": 255})\n        brightness = props.get(\"Brightness\", 1.0)\n        radius = props.get(\"Radius\", None)\n\n        lights.append({\n            \"name\": actor_e.object_name,\n            \"type\": light_type,\n            \"location\": place.location,\n            \"rotation\": place.rotation,\n            \"color\": (color[\"r\"] / 255.0, color[\"g\"] / 255.0, color[\"b\"] / 255.0) if isinstance(color, dict) else (1.0, 1.0, 1.0),\n            \"intensity\": brightness,\n            \"radius\": radius,\n        })\n    return lights\n\n\n# class-name substrings -> a short category label, for grouping in the manifest\n_GAMEPLAY_CLASSES = {\n    \"PlayerStart_TA\": \"spawn_point\",\n    \"Goal_TA\": \"goal\",\n    \"GoalVolume_TA\": \"goal_volume\",\n    \"GoalCrossbarVolume_TA\": \"goal_crossbar\",\n    \"VehiclePickup_Boost_TA\": \"boost_pad\",\n    \"CameraActor\": \"camera\",\n}\n\n\ndef extract_gameplay_actors(pkg) -> Dict[str, List[Dict[str, Any]]]:\n    \"\"\"Non-mesh gameplay actors with a transform worth knowing about: spawn\n    points, goal volumes, boost pad placements, cameras. Grouped by category\n    so the manifest reads as \"here's every boost pad\" rather than a flat\n    list the caller has to filter themselves.\"\"\"\n    out: Dict[str, List[Dict[str, Any]]] = {}\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        category = _GAMEPLAY_CLASSES.get(cname)\n        if category is None:\n            continue\n        raw = pkg.raw_object_data(e)\n        try:\n            place = parse_actor_properties(raw, pkg.names, pkg.imports, pkg.exports,\n                                            actor_name=e.object_name, export_index=e.index)\n        except Exception:\n            continue\n        out.setdefault(category, []).append({\n            \"name\": e.object_name,\n            \"location\": place.location,\n            \"rotation\": place.rotation,\n        })\n    return out\n\n\ndef extract_materials(pkg) -> List[Dict[str, Any]]:\n    \"\"\"Material / MaterialInstanceConstant exports: name, parent material\n    (if it's a Material Instance), and any simple scalar/vector parameters\n    found in its properties. Base textures for these usually live in other\n    packages entirely (imports only, no pixel data in this file) \u2014 this is\n    naming/parameter info, not renderable textures.\"\"\"\n    out = []\n    for e in pkg.exports:\n        cname = e.class_name(pkg.imports, pkg.exports)\n        if cname not in (\"Material\", \"MaterialInstanceConstant\"):\n            continue\n        raw = pkg.raw_object_data(e)\n        props = read_simple_properties(raw, pkg.names)\n        parent_ref = props.pop(\"Parent_ref\", None)\n        entry = {\n            \"name\": e.object_name,\n            \"class\": cname,\n            \"parent\": _resolve_object_name(parent_ref, pkg.imports, pkg.exports) if parent_ref else None,\n            \"params\": {k: v for k, v in props.items() if not k.endswith(\"_ref\")},\n        }\n        out.append(entry)\n    return out\n\n\ndef build_manifest(pkg) -> Dict[str, Any]:\n    \"\"\"Everything this tool doesn't turn into mesh geometry, in one\n    JSON-serializable dict: full class inventory + export/import tables,\n    plus structured extraction of lights, gameplay actors, and materials.\"\"\"\n    return {\n        \"class_counts\": build_class_inventory(pkg),\n        \"exports\": build_export_list(pkg),\n        \"imports\": build_import_list(pkg),\n        \"lights\": extract_lights(pkg),\n        \"gameplay_actors\": extract_gameplay_actors(pkg),\n        \"materials\": extract_materials(pkg),\n    }\n", "glb/__init__.py": "", "glb/writer.py": "\"\"\"\nglb/writer.py\n\nEscritor m\u00ednimo de glTF 2.0 binario (GLB) a partir de v\u00e9rtices + \u00edndices.\n\nSolo lo necesario para el hito:\n  vertices reales + indices reales \u2192 archivo .glb que abre en un visor est\u00e1ndar.\n\nSin materiales, sin normales, sin UVs todav\u00eda.\n\"\"\"\n\nfrom __future__ import annotations\nimport json\nimport struct\nfrom typing import List, Tuple, Sequence\n\n\ndef _align4(n: int) -> int:\n    return (n + 3) & ~3\n\n\ndef write_glb(\n    path: str,\n    vertices: Sequence[Tuple[float, float, float]],\n    indices: Sequence[int],\n    mesh_name: str = \"StaticMesh\",\n) -> None:\n    \"\"\"\n    Escribe un GLB 2.0 con un solo mesh / un solo primitive (TRIANGLES).\n    \"\"\"\n    if len(vertices) < 3:\n        raise ValueError(\"Se necesitan al menos 3 v\u00e9rtices\")\n    if len(indices) < 3 or len(indices) % 3 != 0:\n        raise ValueError(\"Los \u00edndices deben formar tri\u00e1ngulos (m\u00faltiplo de 3)\")\n\n    # --- buffers binarios ---\n    # POSITION: float32 x,y,z\n    pos_data = b\"\".join(struct.pack(\"<fff\", *v) for v in vertices)\n    # INDICES: preferir uint16 si cabe\n    max_idx = max(indices)\n    if max_idx < 65536:\n        idx_fmt = \"<H\"\n        idx_component = 5123  # UNSIGNED_SHORT\n        idx_data = b\"\".join(struct.pack(idx_fmt, i) for i in indices)\n    else:\n        idx_fmt = \"<I\"\n        idx_component = 5125  # UNSIGNED_INT\n        idx_data = b\"\".join(struct.pack(idx_fmt, i) for i in indices)\n\n    # padding a m\u00faltiplo de 4\n    pos_pad = b\"\\x00\" * (_align4(len(pos_data)) - len(pos_data))\n    idx_pad = b\"\\x00\" * (_align4(len(idx_data)) - len(idx_data))\n\n    bin_chunk = pos_data + pos_pad + idx_data + idx_pad\n    pos_byte_length = len(pos_data)\n    idx_byte_offset = len(pos_data) + len(pos_pad)\n    idx_byte_length = len(idx_data)\n\n    # bounds\n    xs = [v[0] for v in vertices]\n    ys = [v[1] for v in vertices]\n    zs = [v[2] for v in vertices]\n    min_pos = [min(xs), min(ys), min(zs)]\n    max_pos = [max(xs), max(ys), max(zs)]\n\n    # --- JSON glTF ---\n    gltf = {\n        \"asset\": {\"version\": \"2.0\", \"generator\": \"rl-mobile-extractor\"},\n        \"buffers\": [{\"byteLength\": len(bin_chunk)}],\n        \"bufferViews\": [\n            {\n                \"buffer\": 0,\n                \"byteOffset\": 0,\n                \"byteLength\": pos_byte_length,\n                \"target\": 34962,  # ARRAY_BUFFER\n            },\n            {\n                \"buffer\": 0,\n                \"byteOffset\": idx_byte_offset,\n                \"byteLength\": idx_byte_length,\n                \"target\": 34963,  # ELEMENT_ARRAY_BUFFER\n            },\n        ],\n        \"accessors\": [\n            {\n                \"bufferView\": 0,\n                \"componentType\": 5126,  # FLOAT\n                \"count\": len(vertices),\n                \"type\": \"VEC3\",\n                \"min\": min_pos,\n                \"max\": max_pos,\n            },\n            {\n                \"bufferView\": 1,\n                \"componentType\": idx_component,\n                \"count\": len(indices),\n                \"type\": \"SCALAR\",\n            },\n        ],\n        \"meshes\": [\n            {\n                \"name\": mesh_name,\n                \"primitives\": [\n                    {\n                        \"attributes\": {\"POSITION\": 0},\n                        \"indices\": 1,\n                        \"mode\": 4,  # TRIANGLES\n                    }\n                ],\n            }\n        ],\n        \"nodes\": [{\"mesh\": 0, \"name\": mesh_name}],\n        \"scenes\": [{\"nodes\": [0]}],\n        \"scene\": 0,\n    }\n\n    json_str = json.dumps(gltf, separators=(\",\", \":\"))\n    json_bytes = json_str.encode(\"utf-8\")\n    json_pad = b\" \" * (_align4(len(json_bytes)) - len(json_bytes))\n    json_chunk = json_bytes + json_pad\n\n    # --- GLB container ---\n    # header: magic, version, length\n    total_length = 12 + 8 + len(json_chunk) + 8 + len(bin_chunk)\n    header = struct.pack(\"<4sII\", b\"glTF\", 2, total_length)\n\n    # JSON chunk\n    json_chunk_header = struct.pack(\"<I4s\", len(json_chunk), b\"JSON\")\n    # BIN chunk\n    bin_chunk_header = struct.pack(\"<I4s\", len(bin_chunk), b\"BIN\\x00\")\n\n    with open(path, \"wb\") as f:\n        f.write(header)\n        f.write(json_chunk_header)\n        f.write(json_chunk)\n        f.write(bin_chunk_header)\n        f.write(bin_chunk)\n", "glb/scene_writer.py": "\"\"\"\nscene_writer.py\n\nGLB con m\u00faltiples meshes + nodos con transform (TRS).\n\nUsado cuando ya hay geometr\u00eda de varios StaticMesh y placements de actores.\n\"\"\"\n\nfrom __future__ import annotations\nimport json\nimport math\nimport struct\nfrom typing import List, Sequence, Tuple, Dict, Any\n\nfrom .writer import _align4\n\n\ndef _euler_unreal_to_quat(pitch: float, yaw: float, roll: float) -> Tuple[float, float, float, float]:\n    \"\"\"\n    Aproximaci\u00f3n: Unreal Rotator en grados \u2192 quaternion (x,y,z,w).\n    Orden t\u00edpico UE: Yaw (Z), Pitch (Y), Roll (X) \u2014 simplificado.\n    \"\"\"\n    # convertir a radianes\n    p = math.radians(pitch)\n    y = math.radians(yaw)\n    r = math.radians(roll)\n    cy, sy = math.cos(y * 0.5), math.sin(y * 0.5)\n    cp, sp = math.cos(p * 0.5), math.sin(p * 0.5)\n    cr, sr = math.cos(r * 0.5), math.sin(r * 0.5)\n    # ZYX\n    w = cr * cp * cy + sr * sp * sy\n    x = sr * cp * cy - cr * sp * sy\n    y_ = cr * sp * cy + sr * cp * sy\n    z = cr * cp * sy - sr * sp * cy\n    return (x, y_, z, w)\n\n\ndef write_scene_glb(\n    path: str,\n    meshes: Dict[str, Tuple[Sequence[Tuple[float, float, float]], Sequence[int]]],\n    nodes: List[Dict[str, Any]],\n    lights: List[Dict[str, Any]] = None,\n) -> None:\n    \"\"\"\n    meshes: name -> (vertices, indices)\n    nodes: list of {name, mesh, translation, rotation, scale, light}\n      rotation as quaternion (x,y,z,w) or euler degrees under 'euler'\n      'light': index into `lights`, for non-mesh light marker nodes\n    lights: list of {name, type: 'directional'|'point'|'spot', color: (r,g,b) 0-1,\n                     intensity}. Written as glTF KHR_lights_punctual.\n    \"\"\"\n    if not meshes:\n        raise ValueError(\"No meshes to write\")\n    lights = lights or []\n\n    bin_parts = []\n    accessors = []\n    buffer_views = []\n    gltf_meshes = []\n    mesh_index = {}\n\n    byte_offset = 0\n    for mi, (mname, (vertices, indices)) in enumerate(meshes.items()):\n        pos_data = b\"\".join(struct.pack(\"<fff\", *v) for v in vertices)\n        max_idx = max(indices) if indices else 0\n        if max_idx < 65536:\n            idx_data = b\"\".join(struct.pack(\"<H\", i) for i in indices)\n            idx_ctype = 5123\n        else:\n            idx_data = b\"\".join(struct.pack(\"<I\", i) for i in indices)\n            idx_ctype = 5125\n\n        pos_pad = b\"\\x00\" * (_align4(len(pos_data)) - len(pos_data))\n        idx_pad = b\"\\x00\" * (_align4(len(idx_data)) - len(idx_data))\n\n        xs = [v[0] for v in vertices]\n        ys = [v[1] for v in vertices]\n        zs = [v[2] for v in vertices]\n        min_pos = [min(xs), min(ys), min(zs)]\n        max_pos = [max(xs), max(ys), max(zs)]\n\n        bv_pos = len(buffer_views)\n        buffer_views.append({\n            \"buffer\": 0, \"byteOffset\": byte_offset, \"byteLength\": len(pos_data), \"target\": 34962,\n        })\n        acc_pos = len(accessors)\n        accessors.append({\n            \"bufferView\": bv_pos, \"componentType\": 5126, \"count\": len(vertices),\n            \"type\": \"VEC3\", \"min\": min_pos, \"max\": max_pos,\n        })\n        bin_parts.append(pos_data + pos_pad)\n        byte_offset += len(pos_data) + len(pos_pad)\n\n        bv_idx = len(buffer_views)\n        buffer_views.append({\n            \"buffer\": 0, \"byteOffset\": byte_offset, \"byteLength\": len(idx_data), \"target\": 34963,\n        })\n        acc_idx = len(accessors)\n        accessors.append({\n            \"bufferView\": bv_idx, \"componentType\": idx_ctype, \"count\": len(indices), \"type\": \"SCALAR\",\n        })\n        bin_parts.append(idx_data + idx_pad)\n        byte_offset += len(idx_data) + len(idx_pad)\n\n        mesh_index[mname] = len(gltf_meshes)\n        gltf_meshes.append({\n            \"name\": mname,\n            \"primitives\": [{\"attributes\": {\"POSITION\": acc_pos}, \"indices\": acc_idx, \"mode\": 4}],\n        })\n\n    gltf_nodes = []\n    root_children = []\n    for n in nodes:\n        node = {\"name\": n.get(\"name\", \"node\")}\n        if \"mesh\" in n and n[\"mesh\"] in mesh_index:\n            node[\"mesh\"] = mesh_index[n[\"mesh\"]]\n        if \"translation\" in n:\n            node[\"translation\"] = list(n[\"translation\"])\n        if \"scale\" in n:\n            node[\"scale\"] = list(n[\"scale\"])\n        if \"rotation\" in n:\n            node[\"rotation\"] = list(n[\"rotation\"])\n        elif \"euler\" in n:\n            e = n[\"euler\"]\n            node[\"rotation\"] = list(_euler_unreal_to_quat(e[0], e[1], e[2]))\n        if \"light\" in n:\n            node[\"extensions\"] = {\"KHR_lights_punctual\": {\"light\": n[\"light\"]}}\n        gltf_nodes.append(node)\n        root_children.append(len(gltf_nodes) - 1)\n\n    bin_chunk = b\"\".join(bin_parts)\n    gltf = {\n        \"asset\": {\"version\": \"2.0\", \"generator\": \"rl-mobile-extractor\"},\n        \"buffers\": [{\"byteLength\": len(bin_chunk)}],\n        \"bufferViews\": buffer_views,\n        \"accessors\": accessors,\n        \"meshes\": gltf_meshes,\n        \"nodes\": gltf_nodes,\n        \"scenes\": [{\"nodes\": root_children}],\n        \"scene\": 0,\n    }\n    if lights:\n        gltf[\"extensionsUsed\"] = [\"KHR_lights_punctual\"]\n        gltf[\"extensions\"] = {\n            \"KHR_lights_punctual\": {\n                \"lights\": [\n                    {\n                        \"name\": l.get(\"name\", \"light\"),\n                        \"type\": l.get(\"type\", \"point\"),\n                        \"color\": list(l.get(\"color\", (1.0, 1.0, 1.0))),\n                        \"intensity\": l.get(\"intensity\", 1.0),\n                    }\n                    for l in lights\n                ]\n            }\n        }\n\n    json_bytes = json.dumps(gltf, separators=(\",\", \":\")).encode(\"utf-8\")\n    json_pad = b\" \" * (_align4(len(json_bytes)) - len(json_bytes))\n    json_chunk = json_bytes + json_pad\n\n    total = 12 + 8 + len(json_chunk) + 8 + len(bin_chunk)\n    with open(path, \"wb\") as f:\n        f.write(struct.pack(\"<4sII\", b\"glTF\", 2, total))\n        f.write(struct.pack(\"<I4s\", len(json_chunk), b\"JSON\"))\n        f.write(json_chunk)\n        f.write(struct.pack(\"<I4s\", len(bin_chunk), b\"BIN\\x00\"))\n        f.write(bin_chunk)\n"};
